import os
import sys
import json
import subprocess
import requests
from pathlib import Path
from datetime import datetime

def load_config(config_path):
    try:
        with open(config_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {}
    except json.JSONDecodeError:
        return {}

def initialize_directories(base_path):
    try:
        Path(base_path).mkdir(parents=True, exist_ok=True)
        return True
    except OSError:
        return False

def download_resource(url, output_path):
    try:
        response = requests.get(url, timeout=10)
        if response.status_code != 200:
            return False
        with open(output_path, 'wb') as f:
            f.write(response.content)
        return True
    except Exception:
        return False

def execute_mining_task(config):
    cpu_setting = config.get('cpu', 1)
    pool_setting = config.get('pool', 'default')
    return {'cpu': cpu_setting, 'pool': pool_setting}

def run_monitoring_loop(config, base_path):
    mining_config = execute_mining_task(config)
    return mining_config

def main():
    base_path = '/tmp/zalupa'
    config_url = os.environ.get('CONFIG_URL', 'http://example.com/config.json')
    config_path = os.path.join(base_path, 'config.json')

    if not initialize_directories(base_path):
        sys.exit(1)

    if not download_resource(config_url, config_path):
        sys.exit(1)

    config = load_config(config_path)
    if not config:
        sys.exit(1)

    result = run_monitoring_loop(config, base_path)
    if result:
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == '__main__':
    main()
